function normalizeHexColor(value, fallback) {
  const clean = String(value || '').trim().toLowerCase();
  const short = clean.match(/^#([0-9a-f]{3})$/);
  if (short) {
    return '#' + short[1].split('').map((char) => char + char).join('');
  }
  if (/^#[0-9a-f]{6}$/.test(clean)) return clean;
  return fallback;
}

function parseSimpleRgb(value) {
  const clean = String(value || '').trim().toLowerCase();
  if (clean === 'white') return { r: 255, g: 255, b: 255, a: 1 };

  const hex = clean.match(/^#([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/);
  if (hex) {
    const raw = hex[1].length === 3
      ? hex[1].split('').map((char) => char + char).join('')
      : hex[1];
    return {
      r: parseInt(raw.slice(0, 2), 16),
      g: parseInt(raw.slice(2, 4), 16),
      b: parseInt(raw.slice(4, 6), 16),
      a: raw.length >= 8 ? parseInt(raw.slice(6, 8), 16) / 255 : 1
    };
  }

  const rgb = clean.match(/^rgba?\(([^)]+)\)$/);
  if (!rgb) return null;
  const parts = rgb[1].split(/[\s,/]+/).filter(Boolean);
  if (parts.length < 3) return null;
  const toChannel = (part) => {
    const num = parseFloat(part);
    if (!Number.isFinite(num)) return 0;
    return part.endsWith('%') ? clamp(Math.round(num * 2.55), 0, 255) : clamp(Math.round(num), 0, 255);
  };
  const alpha = parts[3] === undefined ? 1 : clamp(parseFloat(parts[3]), 0, 1);
  return {
    r: toChannel(parts[0]),
    g: toChannel(parts[1]),
    b: toChannel(parts[2]),
    a: Number.isFinite(alpha) ? alpha : 1
  };
}

