  if (out.style) out.style = normalizeSwitchStyle(out.style);
  if (out.language) out.language = normalizeLanguage(out.language);
  if (out.showGlow !== undefined) out.showGlow = boolAttr(out.showGlow) ? 'true' : 'false';
  if (out.glowColor !== undefined) out.glowColor = normalizeHexColor(out.glowColor, '#ffd95a');
