    showStatus: getConfigInput('showStatus') ? 'true' : 'false',
    showGlow: getConfigInput('showGlow') ? 'true' : 'false',
    glowColor: getConfigInput('glowColor'),
    glowIntensity: getConfigInput('glowIntensity'),
