.real-switch-card[data-style="glass-touch"] .switch-glass { display: grid; }

.material-plate {
  position: relative;
  width: 190px;
  height: 244px;
  box-sizing: border-box;
}

.mount-screw,
.slot-screw,
.brass-screw {
  position: absolute;
  left: 50%;
  z-index: 8;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  transform: translateX(-50%);
  box-shadow: 0 2px 4px #302b23, inset 0 1px 1px #f9f1e3;
}

.screw-top { top: 17px; }
