/* 05 · cast industrial rotary */
.industrial-plate {
  width: 210px;
  height: 230px;
  border: 2px solid #343a3d;
  border-radius: 12px;
  background:
    repeating-linear-gradient(0deg, color-mix(in oklch, #f6f0df 3%, transparent) 0 1px, transparent 1px 4px),
