    stateObj && stateObj.attributes && stateObj.attributes.hs_color || '',
    stateObj && stateObj.attributes && stateObj.attributes.supported_color_modes || ''
  ].join('|');
}

function render(force) {
  if (destroyed) return;

  syncDesignSurface();

  const data = getLightData();
  const style = getSwitchStyle();
  const entityId = getEntityId();
  const icon = getIcon();
  const label = getLabel();
  const language = getLanguage();
  const showBrightness = getShowBrightness();
  const showIcon = getShowIcon();
  const showStatus = getShowStatus();
  const showGlow = getShowGlow();
  const glowColor = getGlowColor();
  const glowIntensity = getGlowIntensity();
  const showWarmColor = getShowWarmColorInSwitch();
  const hasBrightness = hasBrightnessSupport();
  const hasTemperature = hasTemperatureSupport();
  const hasColor = hasColorSupport();
  const showBrightnessTool = hasBrightness && !styleHasInlineBrightness(style);
  const hs = currentHsColor();
  const kelvin = currentKelvin();
  const liveColor = liveColorValue();
  const colorOn = card.dataset.colorOn || '#ffd95a';
  const colorAlt = card.dataset.colorAlt || '#4aa7ff';
  const colorOff = card.dataset.colorOff || '#6f7f96';

  const signature = [
    entityId,
    icon,
    label,
    style,
    data.state,
    data.on,
    data.percent,
    data.unavailable,
    language,
    showBrightness,
    showIcon,
    showStatus,
    showGlow,
    glowColor,
    glowIntensity,
    showWarmColor,
    hasBrightness,
    hasTemperature,
    hasColor,
    showBrightnessTool,
    hs.hue,
    hs.saturation,
    kelvin,
    liveColor,
    colorOn,
    colorAlt,
    colorOff,
    lastSurfaceSignature
  ].join('|');

  if (!force && signature === lastSignature) {
    updateScale();
    return;
  }

  lastSignature = signature;

  card.dataset.style = style;
  card.dataset.active = data.on ? 'on' : 'off';
  card.dataset.unavailable = data.unavailable ? 'true' : 'false';
  card.dataset.language = language;
  card.dataset.showBrightness = showBrightness ? 'true' : 'false';
  card.dataset.showIcon = showIcon ? 'true' : 'false';
  card.dataset.showStatus = showStatus ? 'true' : 'false';
  card.dataset.showGlow = showGlow ? 'true' : 'false';
  card.dataset.glowColor = glowColor;
  card.dataset.glowIntensity = String(glowIntensity);
  card.dataset.showWarmColor = showWarmColor ? 'true' : 'false';
  card.dataset.hasBrightness = hasBrightness ? 'true' : 'false';
  card.dataset.hasTemperature = hasTemperature ? 'true' : 'false';
  card.dataset.hasColor = hasColor ? 'true' : 'false';
  card.dataset.showBrightnessTool = showBrightnessTool ? 'true' : 'false';
  card.dataset.hasLightTools = hasTemperature || hasColor ? 'true' : 'false';
  card.dataset.useLiveColor = liveColor ? 'true' : 'false';
  card.style.setProperty('--nlc-on', colorOn);
  card.style.setProperty('--nlc-alt', colorAlt);
  card.style.setProperty('--nlc-off', colorOff);
  card.style.setProperty('--nlc-glow-color', glowColor);
  applyGlowIntensityVars(showGlow ? glowIntensity : 0);
  card.style.setProperty('--nlc-brightness', data.percent + '%');
  card.style.setProperty('--nlc-ring-angle', (-135 + (data.percent * 2.7)) + 'deg');
  applyTuneCssVars(hs.hue, hs.saturation, liveColor);
  updateWarmColorSettingVisibility();
  applyLanguageText();

  toggleTarget.setAttribute('aria-label', (data.on ? t('turnOff') + ' ' : t('turnOn') + ' ') + label);
  toggleTarget.setAttribute('aria-pressed', data.on ? 'true' : 'false');
  iconEl.setAttribute('icon', icon);
  if (topIconEl) topIconEl.setAttribute('icon', icon);
  labelEl.textContent = label;
  cardNameEl.textContent = label;
  statusEl.textContent = data.unavailable ? t('unavailable') : (data.on ? t('on') : t('off'));
  percentEl.textContent = data.percent + '%';

  const cardPill = root.querySelector('.nlc-card-pill');
  if (cardPill) cardPill.textContent = data.on ? t('on') : t('off');

  root.querySelectorAll('[data-nlc-dot-level]').forEach((button) => {
    const level = Number(button.dataset.nlcDotLevel);
    const active =
      (!data.on && level === 0) ||
      (data.on && data.percent >= 75 && level === 100) ||
      (data.on && data.percent > 0 && data.percent < 75 && level === 50);
    button.classList.toggle('is-active', active);
  });

  syncTuneControls(false);

  updateScale();
}

applyPersistedConfig();
syncDesignSurface();
render(true);
updateScale();

return {
  update(ctx) {
    liveHass = (ctx && ctx.hass) || (host && host.hass) || liveHass;
    const stateSignature = makeHassStateSignature();
    if (stateSignature === lastStateSignature) {
      updateScale();
      return;
    }
    lastStateSignature = stateSignature;
    render(false);
  },
  destroy() {
    destroyed = true;
    try { resizeObserver.disconnect(); } catch {}
    try { surfaceMutationObserver && surfaceMutationObserver.disconnect && surfaceMutationObserver.disconnect(); } catch {}
    if (wrapperStyleSyncTimer) clearTimeout(wrapperStyleSyncTimer);
    wrapperStyleSyncTimer = null;
    wrapperStyleSyncing = false;
    if (resizeFrame) cancelAnimationFrame(resizeFrame);
    try { configPanel && configPanel.classList && configPanel.classList.remove('open'); } catch {}
    try { tunePanel && tunePanel.classList && tunePanel.classList.remove('open'); } catch {}
    unmountConfigPortal();
    unmountTunePortal();
    if (pulseTimer) clearTimeout(pulseTimer);
    if (tuneCommitTimer) clearTimeout(tuneCommitTimer);
    toggleTarget.removeEventListener('click', onToggleClick);
    toggleTarget.removeEventListener('keydown', onToggleKey);
    toggleTarget.removeEventListener('pointerdown', onDimmerPointerDown);
    toggleTarget.removeEventListener('pointermove', onDimmerPointerMove);
    toggleTarget.removeEventListener('pointerup', onDimmerPointerUp);
    toggleTarget.removeEventListener('pointercancel', onDimmerPointerUp);
    configOpen.removeEventListener('click', onConfigOpen);
    configClose.removeEventListener('click', onConfigClose);
    configSave.removeEventListener('click', onConfigSave);
    configPanel.removeEventListener('click', onConfigBackdrop);
    if (entityBlurTimer) clearTimeout(entityBlurTimer);
    if (entityInput) {
      entityInput.removeEventListener('input', onEntityInput);
      entityInput.removeEventListener('focus', onEntityFocus);
      entityInput.removeEventListener('blur', onEntityBlur);
      entityInput.removeEventListener('keydown', onEntityKeydown);
    }
    if (entityMenu) entityMenu.removeEventListener('pointerdown', onEntityMenuPointerDown);
    toggleTarget.removeEventListener('click', onTuneOpen);
    if (tuneClose) tuneClose.removeEventListener('click', onTuneClose);
    if (tunePanel) {
      tunePanel.removeEventListener('click', onTuneBackdrop);
      tunePanel.removeEventListener('pointerdown', onTunePointerStop);
      tunePanel.removeEventListener('pointermove', onTunePointerStop);
      tunePanel.removeEventListener('pointerup', onTunePointerStop);
    }
    if (brightnessInput) {
      brightnessInput.removeEventListener('input', onBrightnessInput);
      brightnessInput.removeEventListener('change', onBrightnessChange);
    }
    if (kelvinInput) {
      kelvinInput.removeEventListener('input', onKelvinInput);
      kelvinInput.removeEventListener('change', onKelvinChange);
    }
    if (hueInput) {
      hueInput.removeEventListener('input', onColorInput);
      hueInput.removeEventListener('change', onColorChange);
    }
    if (saturationInput) {
      saturationInput.removeEventListener('input', onColorInput);
      saturationInput.removeEventListener('change', onColorChange);
    }
  }
};

card.css:
:host,
ha-card,
.shell,
.runtime,
.runtime-content {
  display: block;
  width: 100% !important;
  height: 100% !important;
  min-height: 0 !important;
  box-sizing: border-box !important;
  background: transparent !important;
  box-shadow: none !important;
}

.shell,
.runtime,
.runtime-content {
  padding: 0 !important;
  gap: 0 !important;
  overflow: visible !important;
}

.real-switch-card {
  --nlc-on: #d9a648;
  --nlc-alt: #8d642c;
  --nlc-off: #756f65;
  --nlc-current: var(--nlc-off);
  --nlc-glow: var(--nlc-glow-color, var(--nlc-current));
  --nlc-brightness: 0%;
  --nlc-ring-angle: -135deg;
  --nlc-default-surface: linear-gradient(145deg, #26231e, #171612 62%, #11100d);
  --nlc-surface-background: var(--nlc-design-surface, var(--ddc-card-inner-bg, var(--ddc-card-local-bg, var(--ddc-card-bg, var(--nlc-default-surface)))));
  --nlc-x-scale: 1;
  --nlc-y-scale: 1;
  --nlc-ui-scale: 1;
  --nlc-corner-scale: 1;
  --nlc-radius: 30px;
  width: 100%;
  height: 100%;
  min-width: 50px;
  min-height: 50px;
  position: relative;
  overflow: visible;
  box-sizing: border-box;
  font-family: "Avenir Next", "Gill Sans", "Trebuchet MS", sans-serif;
  background: transparent;
}

.real-switch-card[data-active="on"] { --nlc-current: var(--nlc-on); }
.real-switch-card[data-active="on"][data-use-live-color="true"] { --nlc-current: var(--nlc-live-color, var(--nlc-on)); }

.nlc-stage {
  width: 360px;
  height: 500px;
  position: absolute;
  inset: 0 auto auto 0;
  border-radius: var(--nlc-radius);
  transform-origin: top left;
}

.nlc-switch {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  box-sizing: border-box;
  border: 1px solid color-mix(in oklch, #f1e8d7 10%, transparent);
  border-radius: var(--nlc-radius);
  color: #f1ece2;
  background:
    radial-gradient(circle at 50% 24%, color-mix(in oklch, #e2d4bc 6%, transparent), transparent 34%),
    linear-gradient(155deg, color-mix(in oklch, var(--nlc-surface-background) 92%, #c1ad8e 8%), var(--nlc-surface-background));
  box-shadow:
    inset 0 1px 0 color-mix(in oklch, #fff8e9 10%, transparent),
    inset 0 -24px 60px color-mix(in oklch, #0c0b09 22%, transparent);
  cursor: pointer;
  outline: none;
  user-select: none;
  touch-action: manipulation;
  isolation: isolate;
}

.nlc-switch::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent 0 48%, color-mix(in oklch, #fff3dd 3%, transparent) 50%, transparent 52%),
    repeating-linear-gradient(113deg, transparent 0 11px, color-mix(in oklch, #fff0d5 1.4%, transparent) 12px 13px);
}

.nlc-switch:focus-visible {
  outline: 3px solid color-mix(in oklch, var(--nlc-current) 72%, #f5ead8);
  outline-offset: -4px;
}

.real-switch-card[data-surface="transparent"] .nlc-switch { background: transparent; border-color: transparent; box-shadow: none; }
.real-switch-card[data-surface="transparent"] .nlc-switch::before { display: none; }

.room-wash {
  position: absolute;
  left: 50%;
  top: 38%;
  z-index: 0;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in oklch, var(--nlc-glow) var(--nlc-glow-ambient, 18%), transparent), transparent 68%);
  opacity: .12;
  transform: translate(-50%, -50%) scale(.84);
  transition: transform 280ms cubic-bezier(.65,0,.35,1), opacity 180ms cubic-bezier(.65,0,.35,1);
  pointer-events: none;
}

.real-switch-card[data-active="on"] .room-wash { opacity: .72; transform: translate(-50%, -50%) scale(1); }
.real-switch-card[data-show-glow="false"] .room-wash { display: none; }

.switch-bay {
  position: absolute;
  left: 50%;
  top: calc(42px * var(--nlc-y-scale));
  z-index: 3;
  width: 260px;
  height: 312px;
  transform: translateX(-50%) scale(var(--nlc-ui-scale));
  transform-origin: top center;
}

.switch-model {
  display: none;
  position: absolute;
  inset: 0;
  place-items: center;
}

.real-switch-card[data-style="porcelain-toggle"] .switch-porcelain,
.real-switch-card[data-style="brass-toggle"] .switch-brass,
.real-switch-card[data-style="bakelite-rocker"] .switch-bakelite,
.real-switch-card[data-style="modern-paddle"] .switch-paddle,
.real-switch-card[data-style="industrial-rotary"] .switch-industrial,
.real-switch-card[data-style="knurled-dimmer"] .switch-knurled,
.real-switch-card[data-style="ceramic-dimmer"] .switch-ceramic-dimmer,
.real-switch-card[data-style="euro-push"] .switch-euro,
.real-switch-card[data-style="oak-toggle"] .switch-oak,
.real-switch-card[data-style="glass-touch"] .switch-glass { display: grid; }

.material-plate {
  position: relative;
  width: 190px;
  height: 244px;
  box-sizing: border-box;
}

.mount-screw,
.slot-screw,
.brass-screw {
  position: absolute;
  left: 50%;
  z-index: 8;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  transform: translateX(-50%);
  box-shadow: 0 2px 4px #302b23, inset 0 1px 1px #f9f1e3;
}

.screw-top { top: 17px; }
.screw-bottom { bottom: 17px; }
.slot-screw::after,
.brass-screw::after {
  content: "";
  position: absolute;
  left: 3px;
  right: 3px;
  top: 6px;
  height: 2px;
  border-radius: 1px;
  background: color-mix(in oklch, #20180e 72%, transparent);
  transform: rotate(-8deg);
}

/* 01 · classic American wall toggle */
.porcelain-plate {
  width: 174px;
  height: 260px;
  border: 1px solid #cbc7bf;
  border-radius: 18px 18px 20px 20px;
