    radial-gradient(ellipse at 28% 8%, #fffefa 0 9%, transparent 34%),
    linear-gradient(145deg, #f7f5ef, #dcd9d2 58%, #efede7);
  box-shadow:
    0 23px 38px color-mix(in oklch, #080705 47%, transparent),
