    inset -4px -6px 9px #bbb7af;
}

.porcelain-plate::before {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 12px;
  border: 1px solid color-mix(in oklch, #9f9a92 24%, transparent);
  box-shadow: inset 0 1px 1px #fffefa;
}

