function t(key) {
  const language = getLanguage();
  return (TRANSLATIONS[language] && TRANSLATIONS[language][key]) || TRANSLATIONS.en[key] || key;
}

function styleText(style) {
  const language = getLanguage();
  const styles = (TRANSLATIONS[language] && TRANSLATIONS[language].styles) || TRANSLATIONS.en.styles || {};
  return styles[style] || style;
}

function escapeHtml(value) {
  return String(value === undefined || value === null ? '' : value).replace(/[&<>"']/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[char]));
}

function cloneJson(value, fallback) {
  try {
    return JSON.parse(JSON.stringify(value));
